var t={en:`Staff ask private policy questions. The assistant cites retrieved documents and may draft external email, but must not send it without human approval.`,ua:`Працівники ставлять запитання про приватні правила. Помічник цитує знайдені документи й може готувати листи, але не надсилати без схвалення людиною.`};var i={en:[`Draw identity, policy, permission-aware retrieval, LLM and tool boundaries.`,`Separate untrusted document text from executable instructions.`,`Design citations, evaluation set and human approval for external actions.`],ua:[`Намалюй автентифікацію, політики, пошук із правами, LLM і межі інструментів.`,`Відокрем текст документів від виконуваних команд.`,`Спроєктуй посилання, оцінювання й людське погодження.`]};var n=[{en:`Private documents are filtered before model use.`,ua:`Приватні документи фільтруються до передавання моделі.`},{en:`External side effects require explicit approval.`,ua:`Зовнішні дії потребують явного погодження.`}];var r={scenario:t,tasks:i,checks:n};export{n as checks,r as default,t as scenario,i as tasks};